# rename_lowercase.ps1 â€” renames files in Documents to lowercase
# Run with -Commit to apply changes; default is dry-run only.

param(
    [switch]$Commit
)

$folder = "C:\Users\clope\Documents"
$files  = Get-ChildItem -Path $folder -File

if ($files.Count -eq 0) {
    Write-Host "No files found in $folder"
    exit
}

$changes = @()
foreach ($file in $files) {
    $lower = $file.Name.ToLower()
    if ($file.Name -ne $lower) {
        $changes += [PSCustomObject]@{ Original = $file.Name; Renamed = $lower; FullPath = $file.FullName }
    }
}

if ($changes.Count -eq 0) {
    Write-Host "All files are already lowercase. Nothing to do."
    exit
}

Write-Host "`n$($changes.Count) file(s) would be renamed:`n"
$changes | ForEach-Object { Write-Host "  $($_.Original)  ->  $($_.Renamed)" }

if (-not $Commit) {
    Write-Host "`nDRY RUN â€” no files were changed."
    Write-Host "Re-run with -Commit to apply these renames."
    exit
}

Write-Host "`nApplying renames..."
foreach ($change in $changes) {
    $temp = Join-Path (Split-Path $change.FullPath) ("__tmp__" + $change.Renamed)
    Rename-Item -Path $change.FullPath -NewName $temp
    Rename-Item -Path $temp -NewName $change.Renamed
    Write-Host "  Renamed: $($change.Original)  ->  $($change.Renamed)"
}
Write-Host "`nDone."

