# focus_tracker.ps1 â€” logs the active window title every 10 seconds to a local file.
# Press Ctrl+C to stop.

Add-Type @"
using System;
using System.Runtime.InteropServices;
using System.Text;
public class WinAPI {
    [DllImport("user32.dll")]
    public static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll", CharSet = CharSet.Unicode)]
    public static extern int GetWindowText(IntPtr hWnd, StringBuilder text, int count);
}
"@

$logFile = Join-Path $PSScriptRoot "focus_log_$(Get-Date -Format 'yyyy-MM-dd').txt"
Write-Host "Focus tracker started. Logging to: $logFile"
Write-Host "Press Ctrl+C to stop.`n"

$lastTitle = ""

while ($true) {
    $hwnd   = [WinAPI]::GetForegroundWindow()
    $sb     = New-Object System.Text.StringBuilder 256
    [WinAPI]::GetWindowText($hwnd, $sb, 256) | Out-Null
    $title  = $sb.ToString()

    if ($title -and $title -ne $lastTitle) {
        $entry = "$(Get-Date -Format 'HH:mm:ss')  $title"
        Add-Content -Path $logFile -Value $entry
        Write-Host $entry
        $lastTitle = $title
    }

    Start-Sleep -Seconds 10
}

# tests/test_core.py â€” simple pytest suite for practice-app logic

# ---------------------------------------------------------------------------
# Caesar cipher
# ---------------------------------------------------------------------------
def caesar_encode(text, shift):
    result = ""
    for ch in text:
        if ch.isalpha():
            base = ord("A") if ch.isupper() else ord("a")
            result += chr((ord(ch) - base + shift) % 26 + base)
        else:
            result += ch
    return result


def test_caesar_basic():
    assert caesar_encode("hello world", 3) == "khoor zruog"

def test_caesar_zero_shift():
    assert caesar_encode("abc", 0) == "abc"

def test_caesar_wraps_around():
    assert caesar_encode("xyz", 3) == "abc"

def test_caesar_uppercase():
    assert caesar_encode("ABC", 1) == "BCD"


# ---------------------------------------------------------------------------
# Palindrome check
# ---------------------------------------------------------------------------
def is_palindrome(word):
    return word == word[::-1]


def test_palindrome_true():
    assert is_palindrome("racecar") is True

def test_palindrome_false():
    assert is_palindrome("hello") is False

def test_palindrome_single_char():
    assert is_palindrome("a") is True

def test_palindrome_empty():
    assert is_palindrome("") is True


# ---------------------------------------------------------------------------
# Tip calculation
# ---------------------------------------------------------------------------
def calculate_tip(bill, rate=0.20):
    tip   = bill * rate
    total = bill + tip
    return round(tip, 2), round(total, 2)


def test_tip_twenty_percent():
    tip, total = calculate_tip(64.50)
    assert tip   == 12.90
    assert total == 77.40

def test_tip_zero():
    tip, total = calculate_tip(50.00, 0)
    assert tip   == 0.00
    assert total == 50.00

def test_tip_custom_rate():
    tip, total = calculate_tip(100.00, 0.15)
    assert tip   == 15.00
    assert total == 115.00


# ---------------------------------------------------------------------------
# Temperature conversion
# ---------------------------------------------------------------------------
def fahrenheit_to_celsius(f):
    return round((f - 32) * 5 / 9, 2)


def test_boiling_point():
    assert fahrenheit_to_celsius(212) == 100.0

def test_freezing_point():
    assert fahrenheit_to_celsius(32) == 0.0

def test_body_temp():
    assert fahrenheit_to_celsius(98.6) == 37.0

# unzip_downloads.ps1 â€” unzips .zip files from Downloads into this project folder.
# Default is dry-run. Pass -Commit to actually extract.

param(
    [switch]$Commit
)

$downloads  = "C:\Users\clope\Downloads"
$destination = "C:\Users\clope\OneDrive\Desktop\practice-app"

$zips = Get-ChildItem -Path $downloads -Filter "*.zip" -File

if ($zips.Count -eq 0) {
    Write-Host "No .zip files found in $downloads"
    exit 0
}

Write-Host "$($zips.Count) zip file(s) found:`n"

$allEntries = @()
foreach ($zip in $zips) {
    Write-Host "  $($zip.Name)"
    try {
        $entries = [System.IO.Compression.ZipFile]::OpenRead($zip.FullName).Entries
        foreach ($entry in $entries) {
            $target = Join-Path $destination $entry.FullName
            $exists = Test-Path $target
            $allEntries += [PSCustomObject]@{
                Zip    = $zip.Name
                Entry  = $entry.FullName
                Target = $target
                Overwrites = $exists
            }
            $flag = if ($exists) { " [OVERWRITES]" } else { "" }
            Write-Host "    -> $($entry.FullName)$flag"
        }
    } catch {
        Write-Host "    ERROR reading zip: $_"
    }
}

$overwriteCount = ($allEntries | Where-Object { $_.Overwrites }).Count
if ($overwriteCount -gt 0) {
    Write-Host "`nWARNING: $overwriteCount existing file(s) would be overwritten (marked [OVERWRITES] above)."
}

if (-not $Commit) {
    Write-Host "`nDRY RUN â€” nothing was extracted."
    Write-Host "Re-run with -Commit to extract."
    exit 0
}

