# clean_pycache.ps1 â€” removes __pycache__ folders under C:\Users\clope
# Default is dry-run. Pass -Commit to delete.

param(
    [switch]$Commit
)

$searchRoot = "C:\Users\clope"

Write-Host "Scanning for __pycache__ folders under $searchRoot ...`n"

$folders = Get-ChildItem -Path $searchRoot -Filter "__pycache__" -Recurse -Directory -ErrorAction SilentlyContinue

if ($folders.Count -eq 0) {
    Write-Host "No __pycache__ folders found."
    exit 0
}

$totalSize = ($folders | ForEach-Object {
    (Get-ChildItem $_.FullName -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
} | Measure-Object -Sum).Sum

Write-Host "$($folders.Count) folder(s) found  (~$([math]::Round($totalSize / 1KB)) KB total):`n"
$folders | ForEach-Object { Write-Host "  $($_.FullName)" }

if (-not $Commit) {
    Write-Host "`nDRY RUN â€” nothing was deleted."
    Write-Host "Re-run with -Commit to delete these folders."
    exit 0
}

Write-Host "`nDeleting..."
