$errors  = 0
foreach ($folder in $folders) {
    try {
        Remove-Item -Path $folder.FullName -Recurse -Force
        Write-Host "  Deleted: $($folder.FullName)"
        $deleted++
    } catch {
        Write-Host "  SKIPPED (in use or access denied): $($folder.FullName)"
        $errors++
    }
}

Write-Host "`nDone. $deleted deleted, $errors skipped."

# ping_network.ps1 â€” pings every host on a subnet to see what's online.
#
# Usage:
#   .\ping_network.ps1                    # scans 192.168.1.1â€“254 (default)
#   .\ping_network.ps1 -Subnet 10.0.0    # scans 10.0.0.1â€“254

param(
    [string]$Subnet = "192.168.1"
)

Write-Host "Scanning $Subnet.1 â€“ $Subnet.254 ...`n"

$jobs = 1..254 | ForEach-Object {
    $ip = "$Subnet.$_"
    Start-Job -ScriptBlock {
        param($ip)
        $result = Test-Connection -ComputerName $ip -Count 1 -TimeoutSeconds 1 -Quiet
        [PSCustomObject]@{ IP = $ip; Online = $result }
    } -ArgumentList $ip
}

$results = $jobs | Wait-Job | Receive-Job | Where-Object { $_.Online } | Sort-Object {
    [version]$_.IP
}

$jobs | Remove-Job -Force

if ($results.Count -eq 0) {
    Write-Host "No devices responded on $Subnet.0/24"
    Write-Host "Tip: Check your subnet with: Get-NetIPAddress -AddressFamily IPv4"
} else {
    Write-Host "$($results.Count) device(s) online:`n"
    $results | ForEach-Object { Write-Host "  $($_.IP)" }
}

