import os
import sys

ROOT  = os.path.dirname(os.path.abspath(__file__))
LIMIT = 100

violations = {}

for fname in sorted(os.listdir(ROOT)):
    if not fname.endswith(".py"):
        continue
    path = os.path.join(ROOT, fname)
    long_lines = []
    with open(path, encoding="utf-8") as f:
        for i, line in enumerate(f, 1):
            if len(line.rstrip("\n")) > LIMIT:
                long_lines.append((i, len(line.rstrip("\n")), line.rstrip()))
    if long_lines:
        violations[fname] = long_lines

if not violations:
    print(f"All .py files are within {LIMIT} characters per line.")
    sys.exit(0)

total = sum(len(v) for v in violations.values())
print(f"Found {total} line(s) exceeding {LIMIT} chars in {len(violations)} file(s):\n")

for fname, lines in violations.items():
    print(f"  {fname}")
    for lineno, length, text in lines:
        print(f"    line {lineno:>4}  ({length} chars)  {text[:120]}{'...' if len(text) > 120 else ''}")
    print()

import os
import re

ROOT    = os.path.dirname(os.path.abspath(__file__))
EXTS    = {".py", ".js", ".ts", ".html", ".css", ".md"}
SKIP    = {"backups"}
PATTERN = re.compile(r"#.*TODO|//.*TODO|<!--.*TODO", re.IGNORECASE)

results = []

for dirpath, dirnames, filenames in os.walk(ROOT):
    # skip backup folder
    dirnames[:] = [d for d in dirnames if d not in SKIP]
    for fname in sorted(filenames):
        if os.path.splitext(fname)[1] not in EXTS:
            continue
        path = os.path.join(dirpath, fname)
        rel  = os.path.relpath(path, ROOT)
        with open(path, encoding="utf-8", errors="ignore") as f:
            for i, line in enumerate(f, 1):
                if PATTERN.search(line):
                    results.append((rel, i, line.strip()))

if not results:
    print("No TODO comments found.")
else:
    print(f"Found {len(results)} TODO(s):\n")
    for rel, lineno, text in results:
        print(f"  {rel}:{lineno}  {text}")

